parameters.jsCode:
const telegram = $('Webhook').first().json.body;

// 1. Отримуємо інформацію про нове повідомлення
const chatId = telegram.message.chat.id;
const userText = telegram.message.text;

// 2. Отримуємо всі записи історії із Supabase
const history = $input.all()
  .map(item => item.json)
  .filter(item =>
    ['user', 'assistant'].includes(item.role) &&
    typeof item.content === 'string'
  )
  .reverse()
  .map(item => ({
    role: item.role,
    content: item.content
  }));

// 3. Формуємо контекст для LLM
const messages = [
  {
    role: 'system',
    content: 'You are a helpful customer support assistant.Respond in the same language as the user. Keep responses concise, clear, and practical. Aim for a maximum of 2500 characters. Always finish your answer with a complete sentence. Never deliberately cut off a word, sentence, or list. If the question requires a long explanation, summarize the most important information first. Do not invent company policies, payment details, or refund promises. Use simple formatting suitable for Telegram.'
  },
  ...history,
  {
    role: 'user',
    content: userText
  }
];

// 4. Передаємо результат наступній ноді
return [
  {
    json: {
      chat_id: chatId,
      messages: messages
    }
  }
];

