parameters.jsCode:
const messages = $('Prepare LLM Context').first().json.messages;

const question = messages[messages.length - 1].content;

// Отримуємо результати семантичного пошуку
const documents = $input.all()
  .map(item => item.json)
  .filter(doc =>
    typeof doc.content === 'string' &&
    doc.content.trim() !== ''
  );

// Об'єднуємо документи в текстовий контекст
const context = documents
  .map((doc, index) => {
    return `
[Source ${index + 1}]
Title: ${doc.title}
Similarity: ${Number(doc.similarity).toFixed(3)}

Content:
${doc.content}
`;
  })
  .join('\n---\n');

// Повертаємо один item
return [
  {
    json: {
      question: question,
      context: context,
      retrieved_count: documents.length,
      sources: documents.map(doc => ({
        source_id: doc.source_id,
        title: doc.title,
        similarity: doc.similarity
      }))
    }
  }
];

