    messages: [
      {
        role: "system",
        content: `You are a search query rewriting assistant.

Your task is to rewrite the LAST user message into
a standalone search query using conversation history.

Rules:
1. Use previous messages only to resolve missing context.
2. Preserve the user's original intent.
3. If the last message is already self-contained, keep its meaning.
4. Do not invent facts or assumptions.
5. Return ONLY the rewritten search query.
6. Do not answer the question.
7. Do not add explanations, quotes or JSON.`
      },

      ...$json.messages.filter(m =>
        m.role === "user" ||
        m.role === "assistant"
      )
    ]
  })
}}

parameters.jsCode:
const rawResponse = $input.first().json
  .choices[0].message.content;

// 1. Перетворюємо JSON-рядок на об'єкт
const decision = JSON.parse(rawResponse);

// 2. Перевіряємо допустимі дії
const allowedActions = ['answer', 'escalate'];

if (!allowedActions.includes(decision.action)) {
  throw new Error("Invalid AI action");
}

// 3. Перевіряємо обов'язкові поля
for (const field of ['reply', 'reason', 'ticket_summary']) {
  if (typeof decision[field] !== 'string') {
    throw new Error(`Invalid field: ${field}`);
  }
}

if (!decision.reply.trim()) {
  throw new Error("AI reply is empty");
}

// 4. Отримуємо Telegram chat_id
const chatId = $('Prepare LLM Context')
  .first().json.chat_id;

// 5. Повертаємо результат
return [
  {
    json: {
      chat_id: chatId,
      action: decision.action,
      reply: decision.reply,
      reason: decision.reason,
      ticket_summary: decision.ticket_summary
    }
  }
];
;

